const { useState } = React;

const INITIAL_TIP = "这是通过 attr() 读取的提示文字";

const STYLE = `
  @scope {
    .cb-tip { position: relative; }
    .cb-tip::before {
      content: attr(data-tip);
      position: absolute;
      bottom: calc(100% + 8px);
      left: 50%;
      translate: -50% 4px;
      max-width: 260px;
      width: max-content;
      padding: 4px 10px;
      border-radius: var(--tau-radius-sm);
      background: var(--tau-ink-1);
      color: var(--tau-bg-page);
      font-size: var(--tau-text-sm);
