      white-space: normal;
      pointer-events: none;
      opacity: 0;
      transition: opacity 150ms var(--tau-ease-out), translate 150ms var(--tau-ease-out);
    }
    .cb-tip:hover::before,
    .cb-tip[data-pinned="on"]::before {
      opacity: 1;
      translate: -50% 0;
