const { useEffect, useState } = React;

const PALETTE = ["#3498db", "#e74c3c", "#2ecc71", "#9b59b6", "#f39c12"];
const INITIAL = [
  { label: "React", value: 120, color: "#3498db", hasColor: true },
  { label: "Vue", value: 200, color: "#e74c3c", hasColor: true },
  { label: "Svelte", value: 80, color: "#2ecc71", hasColor: true },
  { label: "Angular", value: 150, color: "#9b59b6", hasColor: true },
];
const MAX = 200;

const STYLE = `
  @scope {
    .cb-bar {
      width: 48px;
      height: attr(data-value type(<length>), 0px);
      background: attr(data-color type(<color>), steelblue);
      border-radius: 6px 6px 0 0;
      transition: height 300ms var(--tau-ease-out), background-color 300ms var(--tau-ease-out);
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Component = () => {
  const [bars, setBars] = useState(INITIAL);
  const [selected, setSelected] = useState(1);
  const [supported, setSupported] = useState(true);

  useEffect(() => {
    setSupported(Boolean(window.CSS?.supports?.("height", "attr(data-value type(<length>), 0px)")));
  }, []);

  const current = bars[selected];
  const update = patch => setBars(list => list.map((bar, index) => (index === selected ? { ...bar, ...patch } : bar)));

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,46%)]">
        <div className="relative flex min-w-0 flex-col rounded-tau-md border border-line-1 px-4 pb-3 pt-6">
          {!supported && (
            <span className="absolute left-3 top-2 rounded-full bg-warn-soft px-2.5 py-0.5 text-tau-sm text-warn">
              当前浏览器不支持带类型的 attr()
            </span>
          )}
          <div className="relative grid h-[200px] grid-cols-4 items-end justify-items-center border-b border-line-1">
            {[50, 100, 150, 200].map(line => (
              <div
                key={line}
                className="pointer-events-none absolute inset-x-0 border-t border-dashed border-line-2"
                style={{ bottom: line }}
              >
                <span className="absolute -top-2.5 left-0 pr-1 font-tau-mono text-tau-tiny text-ink-3">{line}</span>
              </div>
            ))}
            {bars.map((bar, index) => (
              <div
                key={bar.label}
                data-value={`${bar.value}px`}
                data-color={bar.hasColor ? bar.color : undefined}
                onClick={() => setSelected(index)}
                className={`cb-bar relative cursor-pointer ${index === selected ? "outline-2 outline-offset-2 outline-accent" : ""}`}
              />
            ))}
          </div>
          <div className="grid grid-cols-4 justify-items-center pt-2">
            {bars.map((bar, index) => (
              <button
                key={bar.label}
                type="button"
                onClick={() => setSelected(index)}
                className={`w-16 cursor-pointer rounded-tau-sm py-0.5 text-center text-tau-sm ${
                  index === selected ? "bg-accent-soft text-accent-text" : "text-ink-2 hover:bg-hover"
                }`}
              >
                {bar.label}
              </button>
            ))}
          </div>
        </div>
        <pre className="m-0 min-w-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
          <div>
            <span className="text-ink-3">{"<div"}</span> <span className="text-accent-text">class</span>=<span className="text-ok">"chart"</span>
            <span className="text-ink-3">{">"}</span>
          </div>
          {bars.map((bar, index) => (
            <div key={bar.label} className={`rounded-tau-sm px-1 ${index === selected ? "bg-hover" : ""}`}>
              {"  "}
              <span className="text-ink-3">{"<div"}</span> <span className="text-accent-text">data-value</span>=
              <span className="text-ok">"{bar.value}px"</span>
              {bar.hasColor && (
                <>
                  {" "}
                  <span className="text-accent-text">data-color</span>=<span className="text-ok">"{bar.color}"</span>
                </>
              )}
              <span className="text-ink-3">{">"}</span>
              {bar.label}
              <span className="text-ink-3">{"</div>"}</span>
            </div>
          ))}
          <div className="text-ink-3">{"</div>"}</div>
        </pre>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <label className="flex min-w-[220px] flex-1 items-center gap-3">
          <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">data-value</span>
          <input
            type="range"
            min={0}
            max={MAX}
            value={current.value}
            onChange={event => update({ value: Number(event.target.value) })}
            className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
          />
          <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{current.value}px</span>
        </label>
        <div className="flex items-center gap-2">
          <span className="font-tau-mono text-tau-sm text-ink-2">data-color</span>
          {PALETTE.map(color => (
            <button
              key={color}
              type="button"
              aria-label={color}
              onClick={() => update({ color, hasColor: true })}
              className={`size-5 cursor-pointer rounded-full border-2 ${
                current.hasColor && current.color === color ? "border-ink-1" : "border-transparent"
              }`}
              style={{ background: color }}
            />
          ))}
          <ui.Button variant="ghost" size="sm" onClick={() => update({ hasColor: !current.hasColor })}>
            {current.hasColor ? "移除 data-color" : "恢复 data-color"}
          </ui.Button>
        </div>
      </div>
      <p className="m-0 text-tau-sm text-ink-3">
        点选柱子后调整它的属性；去掉 data-color 时 attr() 解析失败，背景回退为 steelblue。
      </p>
    </div>
  );
};

