const { useEffect, useLayoutEffect, useRef, useState } = React;

const ITEMS = [
  { id: "--card-a", label: "React", color: "bg-tag-1" },
  { id: "--card-b", label: "Vue", color: "bg-tag-2" },
  { id: "--card-c", label: "Svelte", color: "bg-tag-3" },
  { id: "--card-d", label: "Angular", color: "bg-tag-4" },
  { id: "--card-e", label: "Solid", color: "bg-tag-5" },
  { id: "--card-f", label: "Astro", color: "bg-accent" },
];

const STYLE = `
  @scope {
    .cb-vt-grid[data-named="on"] .cb-vt-card {
      view-transition-name: attr(data-id type(<custom-ident>));
    }
  }
`;

const shuffle = list => {
  const next = [...list];
  for (let i = next.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [next[i], next[j]] = [next[j], next[i]];
  }
  return next;
};

const Component = () => {
  const gridRef = useRef(null);
  // startViewTransition 的回调要等 DOM 真正更新后才能结束，React 提交后在这里放行
  const commitRef = useRef(null);
  const [items, setItems] = useState(ITEMS);
  const [named, setNamed] = useState(true);
  const [names, setNames] = useState([]);

  useLayoutEffect(() => {
    commitRef.current?.();
    commitRef.current = null;
    setNames([...gridRef.current.children].map(card => getComputedStyle(card).getPropertyValue("view-transition-name")));
  }, [items, named]);
  useEffect(() => () => commitRef.current?.(), []);

  const apply = transform => {
    if (!document.startViewTransition) {
      setItems(transform);
      return;
    }
    document.startViewTransition(
      () =>
        new Promise(resolve => {
          commitRef.current = resolve;
          setItems(transform);
        })
    );
  };

  const nameOf = index => names[index] || (named ? "（浏览器未解析）" : "none");

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="rounded-tau-md border border-line-1 p-4">
          <div ref={gridRef} data-named={named ? "on" : "off"} className="cb-vt-grid grid grid-cols-3 gap-3">
            {items.map(item => (
              <div
                key={item.id}
                data-id={item.id}
                className={`cb-vt-card flex h-16 min-w-0 flex-col items-center justify-center gap-0.5 rounded-tau-sm text-ink-inverse shadow-card ${item.color}`}
              >
                <span className="text-tau-body">{item.label}</span>
                <span className="font-tau-mono text-tau-tiny opacity-80">{item.id}</span>
              </div>
            ))}
          </div>
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <pre className="m-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            <div>.card {"{"}</div>
            <div className={named ? "" : "text-ink-3 line-through"}>
              {"  "}view-transition-name:{" "}
              <span className={named ? "rounded-tau-sm bg-accent-soft px-0.5 text-accent-text" : ""}>
                attr(data-id type(&lt;custom-ident&gt;))
              </span>
              ;
            </div>
            <div>{"}"}</div>
          </pre>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">第 1 张</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{nameOf(0)}</dd>
            <dt className="text-ink-3">第 2 张</dt>
            <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{nameOf(1)}</dd>
            <dt className="text-ink-3">过渡效果</dt>
            <dd className="m-0 text-ink-1">{named ? "每张卡片各自位移" : "整页淡入淡出"}</dd>
          </dl>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-3">
        <ui.Button variant="primary" size="sm" icon={icons.Shuffle} onClick={() => apply(shuffle)}>
          随机排序
        </ui.Button>
        <ui.Button variant="secondary" size="sm" icon={icons.ArrowLeftRight} onClick={() => apply(list => [...list].reverse())}>
          反转
        </ui.Button>
        <ui.Switch checked={named} onCheckedChange={setNamed} label="用 attr() 命名" />
      </div>
    </div>
  );
};
